// Bulkified Parent-Child Mapping Pattern
Map<Id, List<Contact>> accountToContactsMap = new Map<Id, List<Contact>>();

for (Contact con : [SELECT Id, AccountId, LastName, Email FROM Contact WHERE AccountId IN :accountIds]) {
    if (!accountToContactsMap.containsKey(con.AccountId)) {
        accountToContactsMap.put(con.AccountId, new List<Contact>());
    }
    accountToContactsMap.get(con.AccountId).add(con);
}

// Efficiently access contacts for an account without querying again
for (Id accId : accountIds) {
    if (accountToContactsMap.containsKey(accId)) {
        List<Contact> relatedCons = accountToContactsMap.get(accId);
        System.debug('Found ' + relatedCons.size() + ' contacts for account: ' + accId);
    }
}

