public class ComplianceRecalculationBatch implements Database.Batchable<sObject>, Database.Stateful {
    public Integer totalProcessed = 0;

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, LastComplianceReviewDate__c, ComplianceScore__c 
            FROM Account 
            WHERE NeedsReview__c = true
        ]);
    }

    public void execute(Database.BatchableContext bc, List<Account> scope) {
        // Turn off redundant trigger validation
        TriggerBypass.disable('AccountTrigger');

        for (Account acc : scope) {
            acc.ComplianceScore__c = ComplianceCalculator.compute(acc);
            totalProcessed++;
        }

        Database.update(scope, false); // All or none = false for partial success
    }

    public void finish(Database.BatchableContext bc) {
        System.debug('Total accounts processed: ' + totalProcessed);
    }
}
